function e(e,t=Date.now()){return e.finishedAt?new Date(e.finishedAt).toLocaleString():e.status===`running`?t-new Date(e.startedAt).getTime()>36e5?`未结束（可能中断）`:`进行中`:`未记录`}function t(e){if(!e.finishedAt)return`—`;let t=new Date(e.finishedAt).getTime()-new Date(e.startedAt).getTime();if(!Number.isFinite(t)||t<0)return`—`;let n=Math.floor(t/1e3);if(n<60)return`${(t/1e3).toFixed(1)} 秒`;let r=Math.floor(n/60);return r<60?`${r} 分 ${n%60} 秒`:`${Math.floor(r/60)} 小时 ${r%60} 分`}export{e as n,t};